'use strict';
const E=Engine,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v4a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-4"/>',applications:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9"/><circle cx="9" cy="7" r="4"/><path d="M16 3a4 4 0 0 1 0 8"/>',review:'<path d="m9 11 2 2 4-4M9 3H5v18h14V3h-4M9 2h6v4H9z"/>',territories:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',onboarding:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 2v4m8-4v4M8 11h8M8 15h5"/>',assistant:'<path d="M21 11a8 8 0 0 1-8 8H5l-4 3V11a10 10 0 0 1 20 0Z"/><path d="M7 10h.01M12 10h.01M17 10h.01"/>',rules:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.overview}</svg>`;
const stores=[['ST-01','Bengaluru','560001',2019],['ST-02','Bengaluru','560034',2020],['ST-03','Bengaluru','560038',2021],['ST-04','Bengaluru','560066',2022],['ST-05','Bengaluru','560076',2023],['ST-06','Mysuru','570009',2021],['ST-07','Mysuru','570017',2024],['ST-08','Mangaluru','575001',2022],['ST-09','Hubballi-Dharwad','580020',2023],['ST-10','Belagavi','590001',2024]].map(([id,city,pin,year])=>({id,city,pin,year}));
const taskDefs=[['Funding verification','Finance · Verify available funds and any financing conditions.','Finance'],['Site assessment','Expansion · Check address, usable area, floor and site suitability.','Expansion'],['Conditional offer','Expansion · Prepare terms after funding and site checks.','Expansion'],['Acceptance and agreement','Legal · Record acceptance and signed agreement.','Legal'],['Fit-out and inventory','Operations · Complete fit-out, utilities, systems and opening stock.','Operations'],['Training completion','Training · Cover operations, inventory, billing and customer service.','Training'],['Opening readiness','Operations · Verify every prerequisite before opening.','Operations']];
let state={apps:[],territories:[],reference:null,settings:{minInvestment:'',minArea:'',minLaunch:''},tasks:{},taskDates:{},audit:[],source:'Synthetic demo',warnings:[]},results=[],tab='overview',filter='',query='',chat=[],pendingChat=null,importPreview=null,storageOK=true;
function save(){try{localStorage.setItem('franchise-os-v1',JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('Browser storage is unavailable or full. Export a workspace backup before leaving.');}document.querySelector('.local-badge').innerHTML=`<i></i> ${storageOK?'Saved in this browser':'Not saved · export a backup'}`;}
function calculate(){results=E.assess(state.apps,state.territories,stores,state.reference,state.settings);}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function audit(text){state.audit.unshift({at:new Date().toISOString(),text});state.audit=state.audit.slice(0,200);}
function statusTag(s){let color=s==='Recommended'?'green':s==='Waitlisted'?'blue':s==='Location unavailable'||s==='Requirements not met'?'red':s==='Clarification needed'?'amber':'gray';return `<span class="tag ${color}">${esc(s)}</span>`;}
function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function pendingCount(){return state.apps.reduce((n,a)=>n+a.pending.length,0);}
function nav(){const labels={overview:'Overview',applications:'Applications',review:'Data review',territories:'Territories',onboarding:'Onboarding',assistant:'Decision assistant',rules:'Scoring & rules'};$('#nav').innerHTML=Object.entries(labels).map(([k,v])=>`<button data-tab="${k}" class="nav-button ${tab===k?'active':''}">${icon(k)}${v}${k==='review'&&pendingCount()?`<span class="nav-count">${pendingCount()}</span>`:''}</button>`).join('');$('#crumb').textContent=labels[tab]||'Upload';$('#data-label').textContent=state.source.startsWith('Synthetic')?'Synthetic demo data':state.source;}
function render(){calculate();nav();const pages={overview,applications,review,territories,onboarding,assistant,rules,upload};$('#main').innerHTML=(pages[tab]||overview)();bindPage();}
function table(rows,compact=false){if(!rows.length)return `<div class="empty"><h2>No applications here yet</h2>Upload a workbook or change your filters.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Location</th><th>Score range</th><th>Status</th>${compact?'':'<th>Next action</th>'}<th></th></tr></thead><tbody>${rows.map(a=>`<tr class="clickable" data-detail="${esc(a.key)}" tabindex="0" role="button" aria-label="Open ${esc(a.name||a.id||a.key)}"><td><div class="person"><div class="avatar">${esc((a.name||'?').split(/\s+/).slice(0,2).map(n=>n[0]).join(''))}</div><div><strong>${esc(a.name||'Name missing')}</strong><span class="sub">${esc(a.id||'ID missing')}</span></div></div></td><td>${esc(a.city||'City missing')}<span class="sub">${esc(a.pin||'Pin missing')}</span></td><td><span class="score">${a.score}${a.high>a.score?'–'+a.high:''} <small>/100</small></span><span class="score-line"><i style="width:${a.score}%"></i></span></td><td>${statusTag(a.status)}</td>${compact?'':`<td><span class="small-text muted">${esc(nextAction(a))}</span></td>`}<td class="muted">↗</td></tr>`).join('')}</tbody></table></div>`;}
function nextAction(a){return {'Recommended':'Verify funding and site','Clarification needed':a.pending.length?'Confirm data corrections':a.missing.length?'Complete missing information':'Resolve conflicting information','Site needed':'Confirm site and floor','Territory review':'Resolve territory mapping','Location unavailable':'Choose another pin code','Waitlisted':'Review competing applications','Timeline review':'Agree a feasible launch date','Requirements not met':'Review funding or site size'}[a.status]||'Review application';}
function overview(){const rec=results.filter(a=>a.status==='Recommended').length,held=results.filter(a=>a.status==='Clarification needed').length,sites=results.filter(a=>a.status==='Site needed').length,slots=state.territories.reduce((n,t)=>n+(Number.isInteger(t.slots)?t.slots:0),0);return heading('YOUR EXPANSION, AT A GLANCE','A clearer path to your next store.','Review the right partners. Resolve the gaps. Keep every opening moving.',`<span class="demo-tag">${state.source.startsWith('Synthetic')?'SYNTHETIC DEMO':'YOUR WORKBOOK'}</span><button class="button primary" data-tab="upload">${icon('upload')} Upload workbook</button>`)+`<div class="stats">${[[results.length,'Total applications','Every application stays in view','applications'],[rec,'Recommended partners','Subject to funding and site checks','review'],[held+sites,'Need your attention',`${held} data clarifications · ${sites} site checks`,'assistant'],[state.territories.length,'Active territories',`${rec} of ${slots} expansion slots recommended`,'territories']].map(([n,l,d,i])=>`<div class="stat"><div class="stat-label">${l}${icon(i)}</div><div class="stat-value">${n.toString().padStart(2,'0')}</div><div class="stat-note ${i==='review'?'green':''}">${d}</div></div>`).join('')}</div><div class="grid-main"><section class="panel"><div class="panel-top"><div><h2>A little attention. A lot of progress.</h2><div class="panel-subtitle">The next actions that keep applications moving.</div></div><span class="tag amber">${held+sites} to review</span></div><div class="panel-body"><div class="attention-row"><div class="attention-symbol">✓</div><div><strong>Confirm proposed corrections</strong><p>${pendingCount()} values need a quick check before scoring.</p></div><button class="text-button" data-tab="review">Review →</button></div><div class="attention-row"><div class="attention-symbol">?</div><div><strong>Fill in the missing pieces</strong><p>${held} applications have incomplete or conflicting information.</p></div><button class="text-button" data-filter="Clarification needed">View →</button></div><div class="attention-row"><div class="attention-symbol">⌖</div><div><strong>Help partners find the right space</strong><p>${sites} applications need confirmed site details.</p></div><button class="text-button" data-filter="Site needed">View →</button></div><div class="insight"><strong>Good candidates don’t disappear because a field is blank.</strong>Incomplete applications remain visible. Their score range shows what is confirmed and what could change.</div></div></section><div><section class="panel"><div class="panel-top"><h2>The expansion pipeline</h2><span class="eyebrow">LIVE</span></div><div class="panel-body">${[['Applications received',results.length],['Ready for verification',rec],['Waiting for a slot',results.filter(a=>a.status==='Waitlisted').length],['Opening checks complete',results.filter(a=>a.status==='Recommended'&&completed(a)===7).length]].map(([l,n])=>`<div class="funnel-row"><div class="funnel-head"><span>${l}</span><strong>${n}</strong></div><div class="bar"><span style="width:${results.length?n/results.length*100:0}%"></span></div></div>`).join('')}</div></section></div></div><section class="panel section-gap"><div class="panel-top"><div><h2>Partners worth a closer look</h2><div class="panel-subtitle">Recommended partners first, then applications with unresolved details.</div></div><button class="text-button" data-tab="applications">View all applications →</button></div>${table([...results].sort((a,b)=>(b.status==='Recommended')-(a.status==='Recommended')||b.score-a.score).slice(0,5),true)}</section><div class="grid-main section-gap"><section class="panel"><div class="panel-top"><h2>Recent activity</h2></div><div class="panel-body">${state.audit.length?state.audit.slice(0,3).map(a=>`<div class="activity-row">${esc(a.text)}<small>${new Date(a.at).toLocaleString()}</small></div>`).join(''):'<p class="muted small-text">Corrections, application updates and onboarding progress will appear here.</p>'}</div></section><div class="callout"><div class="eyebrow">DECISIONS, EXPLAINED</div><h2>Ask what’s holding a partner back.</h2><p>Get a clear reason, or propose an update and see what changes.</p><button class="button small" data-tab="assistant">Open decision assistant ↗</button></div></div>`;}
function applications(){let list=results.filter(a=>(!filter||a.status===filter)&&(!query||[a.id,a.name,a.city,a.pin].some(v=>String(v||'').toLowerCase().includes(query.toLowerCase())))).sort((a,b)=>b.score-a.score);return heading('PARTNER PIPELINE','Every application, accounted for.','Scores help you prioritise. Status tells you what can happen next.',`<button class="button primary" data-tab="upload">Upload workbook</button>`)+`<section class="panel"><div class="panel-top"><div><h2>Applications <span class="muted">${list.length}</span></h2><div class="panel-subtitle">Confirmed score to possible score · click a partner to see the reasoning.</div></div></div><div class="table-toolbar"><input id="search" class="input search" placeholder="Search name, ID, city or pin…" value="${esc(query)}" aria-label="Search applications"><select id="status-filter" class="input" aria-label="Filter by status"><option value="">All statuses</option>${[...new Set(results.map(a=>a.status))].map(s=>`<option ${s===filter?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div id="app-table">${table(list)}</div></section><p class="hint">Tie-breaks: confirmed score, sooner stated launch, then application ID. Unknown score components never inflate the confirmed score.</p>`;}
function review(){let cards=[];for(let a of state.apps)for(let [i,p] of a.pending.entries())cards.push(`<div class="review-card"><div class="actions" style="justify-content:space-between"><div><strong>${esc(a.name||a.id||a.key)}</strong> <span class="sub">${esc(a.id)} · ${esc(E.labels[p.field])}</span></div><button class="text-button" data-detail="${esc(a.key)}">Open application ↗</button></div><div class="review-values"><div><small>ORIGINAL VALUE</small>${esc(p.raw)}</div><span class="muted">→</span><div><small>PROPOSED VALUE</small><input class="input" id="correction-${esc(a.key)}-${i}" type="number" min="0" step="any" value="${esc(p.proposed??'')}" placeholder="Enter a confirmed number" aria-label="Confirmed ${esc(E.labels[p.field])}"></div></div><button class="button primary small" data-confirm-correction="${esc(a.key)}" data-index="${i}">Confirm correction</button> <button class="button small" data-reject-correction="${esc(a.key)}" data-index="${i}">Mark as missing</button></div>`);return heading('DATA QUALITY','Clean data. With your confirmation.','Original answers are preserved. Proposed changes take effect only when confirmed.')+`<section class="panel"><div class="panel-top"><h2>Proposed corrections</h2><span class="tag amber">${cards.length} awaiting confirmation</span></div>${cards.join('')||'<div class="empty"><h2>No corrections waiting</h2>Missing or contradictory information can still need review.</div>'}</section><section class="panel section-gap"><div class="panel-top"><h2>Applications needing clarification</h2></div>${table(results.filter(a=>a.status==='Clarification needed'),true)}</section>${state.warnings.length?`<div class="info-row warning">${state.warnings.map(esc).join('<br>')}</div>`:''}`;}
function territories(){return heading('GEO-SELECTION','Make room for the right partner.','One store per pin code. Recommendations always respect territory capacity.')+`<div class="territory-grid">${state.territories.map(t=>{let rec=results.filter(a=>a.territory===t.id&&a.status==='Recommended'),app=results.filter(a=>a.territory===t.id);return `<section class="panel territory-card"><div class="actions" style="justify-content:space-between"><span class="eyebrow">${esc(t.id)}</span><span class="tag ${t.priority==='High'?'green':t.priority==='Medium'?'amber':'gray'}">${esc(t.priority||'Unknown')} priority</span></div><div class="city-name">${esc(t.city)}</div><div class="small-text muted">${esc(t.tier)} · ${esc(t.state)}</div><div class="pin-list">${esc(t.pins.join(' · '))}</div>${t.issues?.length?`<div class="info-row warning">${t.issues.map(esc).join('<br>')}</div>`:''}<div class="territory-meta"><div>Applications<strong>${app.length}</strong></div><div>Recommended<strong>${rec.length}<span class="muted" style="font-size:12px"> / ${esc(t.slots??'?')}</span></strong></div></div><div class="compact">${rec.map(a=>`<button class="text-button" data-detail="${esc(a.key)}">${esc(a.name)} ↗</button><br>`).join('')||'<span class="hint">No partners recommended yet</span>'}</div></section>`;}).join('')||'<div class="empty">Upload territories to map your expansion.</div>'}</div><section class="panel section-gap"><div class="panel-top"><div><h2>Existing store footprint</h2><div class="panel-subtitle">Fixed brand list from the case · these 10 pin codes are unavailable.</div></div></div><div class="table-wrap"><table><thead><tr><th>Store</th><th>City</th><th>Pin code</th><th>Opened</th></tr></thead><tbody>${stores.map(s=>`<tr><td>${s.id}</td><td>${s.city}</td><td>${s.pin}</td><td>${s.year}</td></tr>`).join('')}</tbody></table></div></section>`;}
function completed(a){return Object.values(state.tasks[a.key]||{}).filter(Boolean).length;}
function onboarding(){let list=results.filter(a=>a.status==='Recommended'||completed(a)>0);return heading('OPENING READINESS','From a good fit to an open store.','Each partner gets a sequenced checklist. Complete prerequisites before moving forward.')+`<section class="panel"><div class="panel-top"><h2>Partner onboarding</h2><span class="tag green">${list.length} partners</span></div>${list.map(a=>`<div class="onboarding-summary"><div><strong>${esc(a.name)}</strong><span class="sub">${esc(a.id)} · ${esc(a.city)} · Training: ${esc(a.language||'Confirm language')}</span><div class="compact">${statusTag(a.status)}</div></div><div><span class="small-text muted">${completed(a)} of 7 steps complete</span><div class="bar compact"><span style="width:${completed(a)/7*100}%"></span></div></div><button class="button small" data-detail="${esc(a.key)}">Open checklist ↗</button></div>`).join('')||'<div class="empty"><h2>Your next opening starts here</h2>Recommended partners will appear with their verification and training plan.</div>'}</section><div class="info-row">Recommendations are provisional. Funding, site suitability and signed agreements are verified in the checklist. Training completion is recorded by the operator; this MVP does not provide a learning-management system.</div>`;}
function assistant(){return heading('DECISION ASSISTANT','A reason behind every decision.','Ask about a partner, or propose a change. You confirm every update.')+`<div class="chat-layout"><section class="panel"><div class="panel-top"><h2>Talk through the pipeline</h2><span class="tag green">Rules-based assistant</span></div><div class="chat-log" id="chat-log">${(chat.length?chat:[{text:'Try “Why is APP-012 on hold?” or “APP-012 has now found a ground-floor space.”\n\nI explain the current rules and propose supported field updates. Changes are confirmed before they affect the pipeline.',user:false}]).map(m=>`<div class="message ${m.user?'user':''}">${esc(m.text)}</div>`).join('')}${pendingChat?`<div class="message"><strong>Confirm proposed update</strong><br>${esc(pendingChat.id)} · ${esc(E.labels[pendingChat.field])}<br>${esc(state.apps.find(a=>a.key===pendingChat.key)?.[pendingChat.field]??'Missing')} → ${esc(pendingChat.value)}<br><div class="actions compact"><button class="button primary small" id="confirm-chat">Confirm & reassess</button><button class="button small" id="cancel-chat">Cancel</button></div></div>`:''}</div><form class="chat-input" id="chat-form"><input class="input" id="chat-text" placeholder="Ask about an application or describe an update…" aria-label="Message to decision assistant" required><button class="button primary">Send ↗</button></form></section><aside><section class="panel"><div class="panel-top"><h2>Start with a question</h2></div><div class="panel-body">${['Why is APP-012 on hold?','Explain the score for APP-001','APP-012 has now found a ground-floor space','APP-008 investment is 35 lakh','APP-006 area is 500 sq ft'].map(s=>`<button class="prompt" data-prompt="${esc(s)}">${esc(s)} ↗</button>`).join('')}<p class="hint">Supports application IDs, explanations, floor, ownership, investment, area, launch months, experience and pin updates. Use the application editor for other changes.</p></div></section></aside></div>`;}
function rules(){return heading('ASSESSMENT POLICY','Clear rules. Consistent decisions.','Your 60 / 10 / 30 model, with the assumptions visible.')+`<div class="settings-grid"><section class="panel"><div class="panel-top"><h2>How the score adds up</h2></div><div class="panel-body">${[['Investment & premises',60,'Investment 22.5 · ownership 15 · area 22.5'],['Launch readiness',10,'Time to open 10 · fewer months scores higher'],['Experience & suitability',30,'Retail experience 15 · floor 10 · previous business 5']].map(([s,n,d])=>`<div class="weight-row"><strong>${s}</strong><strong>${n}%</strong></div><div class="bar"><span style="width:${n}%;background:#2c7359"></span></div><p class="hint">${d}</p>`).join('')}<div class="rule-code">60 × (investment + ownership + area) / 8<br>+ 10 × launch / 3<br>+ 30 × (experience + floor + business) / 6</div><p class="small-text muted">90th percentile and above: 3 points<br>50th to below 90th: 2 points<br>30th to below 50th: 1 point<br>Below 30th: 0 points</p><p class="hint">Zero investment, area or retail experience earns zero points. Launch ranking is reversed. Owned 2, rented 1, not identified 0. Ground 2, confirmed first 1, other confirmed floor 0. Prior business 1 only with explicit evidence.</p></div></section><section class="panel"><div class="panel-top"><h2>Brand requirements</h2><span class="tag gray">Editable assumptions</span></div><div class="panel-body"><p class="small-text muted">The case provides no absolute brand minimums. Leave a field blank to keep that check off. A high percentile alone does not establish financial or site viability.</p><form id="settings-form" class="form-grid"><label class="full">Minimum investment (₹ lakh)<input class="input" name="minInvestment" type="number" min="0" step="any" placeholder="Not configured" value="${esc(state.settings.minInvestment)}"></label><label class="full">Minimum usable area (sq ft)<input class="input" name="minArea" type="number" min="0" step="any" placeholder="Not configured" value="${esc(state.settings.minArea)}"></label><label class="full">Minimum preparation time (months)<input class="input" name="minLaunch" type="number" min="0" step="any" placeholder="Not configured" value="${esc(state.settings.minLaunch)}"></label><button class="button primary full">Save rules & reassess</button></form></div></section><section class="panel"><div class="panel-top"><h2>Percentile reference</h2><span class="tag gray">Frozen per import</span></div><div class="panel-body"><p class="small-text muted">Compare within city tier when there are at least five valid observations with variation; otherwise use the whole upload. Tied values use their shared midrank. Small or identical-value cohorts remain unscored, with their possible contribution visible in the score range.</p><p class="small-text muted">Corrections and follow-up updates use the original reference to keep other applicants’ scores stable. Rebuilding updates everyone’s benchmark and is recorded in activity.</p><button class="button" id="rebase">Rebuild reference from confirmed data</button></div></section><section class="panel"><div class="panel-top"><h2>Allocation and safeguards</h2></div><div class="panel-body"><ul class="help-list"><li>Missing required fields are retained and flagged.</li><li>Existing store pin codes are blocked.</li><li>One recommendation per pin code; territory slots are enforced.</li><li>Unidentified premises, unknown floor or missing area pause site readiness.</li><li>Territory conflicts require clarification.</li><li>Rank by confirmed score, launch time, then application ID.</li><li>No market-demand, revenue or payback estimates are inferred from this dataset.</li></ul></div></section></div>`;}
function upload(){return heading('IMPORT APPLICATIONS','Bring your next opportunities in.','Upload the original test format. Incomplete records are welcome.',`<a class="button" href="template.xlsx" download>Download template ↓</a>`)+`<section class="panel"><div class="panel-top"><div><h2>Upload an Excel workbook</h2><div class="panel-subtitle">Applications and Territories · fixed existing-store list stays protected.</div></div><span class="tag gray">.xlsx · up to 10 MB</span></div><div class="panel-body"><div class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="Choose XLSX workbook"><div class="drop-icon">${icon('upload')}</div><h2>Drop your workbook here</h2><p>or click to choose a file from your computer.<br>Your file is processed in your browser.</p><span class="button primary">Choose workbook</span></div><label class="check-line"><input type="checkbox" id="include-examples"> Include row 3 examples from the supplied template</label><p class="hint">The template says row 3 is an example and real entries begin at row 4. Turn this on to test the template’s sample application and territory.</p><div id="import-preview"></div><div class="info-row">Each import replaces this browser’s current workspace after confirmation. Export a backup first if you want to keep your current work.</div><div class="actions"><button class="button" id="load-demo">Load synthetic demo</button><button class="button" id="restore">Restore workspace backup</button></div></div></section>`;}
function modal(content){$('#overlay').innerHTML=`<section class="drawer" role="dialog" aria-modal="true" aria-label="Application workspace">${content}</section>`;$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#overlay').querySelector('button,input,select')?.focus();}
function close(){ $('#overlay').hidden=true;$('#overlay').innerHTML='';document.body.style.overflow='';}
function detail(key){let a=results.find(a=>a.key===key);if(!a)return;let tasks=state.tasks[key]||{},dates=state.taskDates[key]||{};modal(`<div class="drawer-head"><div><span class="eyebrow">${esc(a.id||'ID missing')} · ${esc(a.city||'City missing')}</span><h2>${esc(a.name||'Name missing')}</h2>${statusTag(a.status)}</div><button class="close" data-close aria-label="Close dialog">×</button></div><div class="detail-score"><div><div class="eyebrow">CONFIRMED TO POSSIBLE SCORE</div><div class="big-score">${a.score}${a.high>a.score?'–'+a.high:''}<small> /100</small></div></div><div><div class="small-text">${a.high>a.score?'Some components remain unknown':'All components scored'}</div><small>Reference frozen at last import/rebuild</small></div></div><section class="panel"><div class="panel-top"><h2>Why this decision?</h2></div><div class="panel-body">${a.reasons.map(r=>`<div class="reason">${esc(r)}</div>`).join('')}<div class="info-row"><strong>Next action:</strong> ${esc(nextAction(a))}</div></div></section><section class="panel"><div class="panel-top"><h2>Score breakdown</h2></div><div class="table-wrap"><table class="breakdown"><thead><tr><th>Component</th><th>Points</th><th>Contribution</th></tr></thead><tbody>${a.components.map(c=>`<tr><td>${esc(c.label)}<span class="sub">${esc(c.detail)}</span></td><td>${c.points===null?'Unknown':c.points+' / '+c.max}</td><td>${c.points===null?'0–'+c.weight:c.contribution.toFixed(1)} / ${c.weight}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-top"><h2>Application details</h2><button class="button small" data-edit="${esc(key)}">Edit application</button></div><div class="panel-body"><div class="form-grid">${E.fields.filter(f=>!['name','id'].includes(f)).map(f=>`<div><span class="hint">${esc(E.labels[f])}</span><div class="small-text">${esc(a[f]??'Missing')}</div></div>`).join('')}</div></div></section><section class="panel"><div class="panel-top"><h2>Opening checklist</h2><span class="tag gray">${completed(a)} / 7</span></div><div class="panel-body"><p class="small-text muted">Training language: ${esc(a.language||'Confirm language before completing training')}. ${a.experience===0?'Add introductory retail practice and supervised store exposure.':'Include brand-specific systems, inventory and customer-service practice.'}</p>${a.status!=='Recommended'?'<div class="info-row warning">Onboarding is paused until the application is recommended again. Resolve its current next action first.</div>':''}${taskDefs.map(([title,desc,owner],i)=>`<div class="task-row ${tasks[i]?'done':''}"><input type="checkbox" data-task="${esc(key)}" data-task-index="${i}" ${tasks[i]?'checked':''} ${a.status!=='Recommended'||(i>0&&!tasks[i-1])||(i===5&&!a.language)?'disabled':''} aria-label="Complete ${title}"><div style="flex:1"><strong>${i+1}. ${title}</strong><p>${desc}</p><label class="hint">Due date <input class="input" style="font-size:10px;min-height:26px;padding:4px" type="date" data-task-date="${esc(key)}" data-task-index="${i}" value="${esc(dates[i]||'')}" aria-label="Due date for ${title}"></label></div></div>`).join('')}</div></section><details class="small-text muted"><summary>Original imported values</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(a.raw,null,2))}</pre></details>`);}
function edit(key){let a=state.apps.find(a=>a.key===key);if(!a)return;let choices={city:Object.keys(E.cities),state:['Karnataka'],space:['Owned','Rented','Not yet identified'],floor:['Ground','Upper','Mall unit','Not known','First','Other confirmed'],language:['Kannada','English','Hindi']};modal(`<div class="drawer-head"><div><div class="eyebrow">CONFIRM AN UPDATE</div><h2>Edit ${esc(a.id||'application')}</h2></div><button class="close" data-close aria-label="Close dialog">×</button></div><p class="small-text muted">Changes update the assessment and territory allocation. Original imported values are retained.</p><form id="edit-form" data-key="${esc(key)}"><div class="form-grid">${E.fields.map(f=>`<label class="${f==='notes'||f==='business'?'full':''}">${esc(E.labels[f])}${choices[f]?`<select class="input" name="${f}"><option value="">Missing / unconfirmed</option>${choices[f].map(c=>`<option value="${esc(c)}" ${a[f]===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`:f==='notes'||f==='business'?`<textarea class="input" name="${f}">${esc(a[f])}</textarea>`:`<input class="input" name="${f}" ${E.numeric.includes(f)?'type="number" min="0" step="any"':''} value="${esc(a[f])}" ${f==='pin'?'inputmode="numeric" maxlength="6"':''}>`}</label>`).join('')}</div><div class="actions section-gap"><button class="button primary">Confirm changes & reassess</button><button type="button" class="button" data-detail="${esc(key)}">Cancel</button></div></form>`);}
function applyPatch(key,patch,why){let a=state.apps.find(a=>a.key===key);if(!a)return;let before=results.find(x=>x.key===key);let changed=Object.fromEntries(Object.entries(patch).filter(([k,v])=>a[k]!==v));state.tasks[key]=E.invalidateTasks(state.tasks[key]||{},changed);Object.assign(a,patch);a.pending=a.pending.filter(p=>!(p.field in patch));calculate();let after=results.find(x=>x.key===key);audit(`${a.id||a.key}: ${why}. ${before?.status} → ${after.status}; score ${before?.score} → ${after.score}.`);save();render();return {before,after};}
function explanation(a){return `${a.id} · ${a.name||'Name missing'}\n${a.status} · Score ${a.score}${a.high>a.score?'–'+a.high:''}/100\n\n${a.reasons.join('\n')}\n\nNext action: ${nextAction(a)}.\n\n${a.components.map(c=>`${c.label}: ${c.points===null?'unknown':c.points+'/'+c.max+' points'} (${c.points===null?'0–'+c.weight:c.contribution.toFixed(1)} of ${c.weight})`).join('\n')}`;}
function send(text){if(!text.trim())return;chat.push({text,user:true});pendingChat=null;let p=E.parseUpdate(text,state.apps);if(p.error)chat.push({text:p.error});else if(p.explain){let a=results.find(a=>a.key===p.key);chat.push({text:explanation(a)});}else pendingChat=p;render();$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}
function download(name,text,type){let blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportModal(){modal(`<div class="drawer-head"><h2>Save your results</h2><button class="close" data-close aria-label="Close dialog">×</button></div><p class="small-text muted">This workspace is stored in this browser. Use a backup to continue on another device.</p><div class="actions"><button class="button primary" id="export-csv">Download assessment CSV</button><button class="button" id="export-json">Download workspace backup</button><button class="button" id="restore">Restore a backup</button></div><div class="info-row">CSV includes decisions and next actions. JSON preserves applications, corrections, rules, frozen benchmarks, tasks and activity.</div>`);}
async function parseFile(file){if(!file)return;try{toast('Reading workbook…');let sheets=await WorkbookReader.readWorkbook(file),include=$('#include-examples')?.checked||false;let parsed=WorkbookReader.importRows(sheets,include);importPreview={...parsed,source:file.name};$('#import-preview').innerHTML=`<div class="info-row"><strong>${esc(file.name)}</strong><br>${parsed.apps.length} applications · ${parsed.territories.length} territories · ${parsed.apps.reduce((n,a)=>n+a.pending.length,0)} proposed corrections</div>${parsed.warnings.length?`<div class="info-row warning">${parsed.warnings.map(esc).join('<br>')}</div>`:''}<button id="confirm-import" class="button primary" ${!parsed.apps.length?'disabled':''}>Replace workspace & import</button>`;toast('Workbook read. Review the summary before importing.');}catch(e){toast(e.message||'The workbook could not be read.');}$('#file').value='';}
async function loadDemo(initial=false){try{let data=await(await fetch('demo.json')).json();pendingChat=null;chat=[];state={apps:data.apps.map((a,i)=>E.normalize(a,'demo-'+i)),territories:data.territories,reference:null,settings:{minInvestment:'',minArea:'',minLaunch:''},tasks:{},taskDates:{},audit:[],source:'Synthetic demo · 24 applicants',warnings:[]};state.reference=E.benchmarks(state.apps);audit('Loaded synthetic demo data. These are fictional applicants.');save();tab='overview';location.hash='overview';render();if(!initial)toast('Synthetic demo loaded.');}catch(e){toast('Could not load demo. Upload a workbook to get started.');render();}}
function bindPage(){if($('#search'))$('#search').oninput=e=>{query=e.target.value;let pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};if($('#status-filter'))$('#status-filter').onchange=e=>{filter=e.target.value;render();};if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();send($('#chat-text').value);};if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();state.settings=Object.fromEntries(new FormData(e.target));audit('Updated brand minimum requirements and reassessed all applications.');save();render();toast('Rules saved. Allocation reassessed.');};if($('#dropzone')){let d=$('#dropzone');d.onclick=()=>$('#file').click();d.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file').click();}};d.ondragover=e=>{e.preventDefault();d.classList.add('drag');};d.ondragleave=()=>d.classList.remove('drag');d.ondrop=e=>{e.preventDefault();d.classList.remove('drag');parseFile(e.dataTransfer.files[0]);};}}
document.addEventListener('click',e=>{let el=e.target.closest('button,a,tr[data-detail]');if(!el)return;let d=el.dataset;if(d.tab){tab=d.tab;location.hash=tab;render();}else if(d.filter){filter=d.filter;query='';tab='applications';location.hash=tab;render();}else if(d.detail)detail(d.detail);else if(d.edit)edit(d.edit);else if('close'in d)close();else if(d.prompt)send(d.prompt);else if(d.confirmCorrection){let a=state.apps.find(a=>a.key===d.confirmCorrection),p=a.pending[Number(d.index)],v=document.getElementById('correction-'+a.key+'-'+d.index).value;if(v===''||!Number.isFinite(Number(v))||Number(v)<0){toast('Enter a valid non-negative number to confirm.');return;}applyPatch(a.key,{[p.field]:Number(v)},`Confirmed ${E.labels[p.field]}: ${p.raw} → ${v}`);toast('Correction confirmed. Application reassessed.');}else if(d.rejectCorrection){let a=state.apps.find(a=>a.key===d.rejectCorrection),p=a.pending[Number(d.index)];applyPatch(a.key,{[p.field]:null},`Marked ${E.labels[p.field]} as missing`);}else if(el.id==='load-demo'){if(confirm('Replace this browser’s workspace with synthetic demo data? Export a backup first if needed.'))loadDemo();}else if(el.id==='restore')$('#restore-file').click();else if(el.id==='export')exportModal();else if(el.id==='export-json')download('franchise-workspace.json',JSON.stringify({version:1,state},null,2),'application/json');else if(el.id==='export-csv'){const safe=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};let rows=[['Application ID','Name','City','Pin','Status','Confirmed score','Possible score','Territory','Reason','Next action'],...results.map(a=>[a.id,a.name,a.city,a.pin,a.status,a.score,a.high,a.territory,a.reasons.join(' '),nextAction(a)])];download('franchise-assessments.csv','\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}else if(el.id==='rebase'){if(confirm('Rebuild percentile references? This may change every applicant’s score and allocation.')){state.reference=E.benchmarks(state.apps);audit('Rebuilt percentile references using currently confirmed data.');save();render();toast('References rebuilt. Scores and allocations updated.');}}else if(el.id==='confirm-chat'){let p=pendingChat;pendingChat=null;let r=applyPatch(p.key,{[p.field]:p.value},`Confirmed assistant update to ${E.labels[p.field]}: ${p.value}`);chat.push({text:`Updated ${p.id}: ${E.labels[p.field]} → ${p.value}.\n\n${r.before.status} → ${r.after.status}. Confirmed score ${r.before.score} → ${r.after.score}.\n\n${r.after.reasons.join('\n')}\n\nNext action: ${nextAction(r.after)}.`});render();$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}else if(el.id==='cancel-chat'){pendingChat=null;chat.push({text:'Update cancelled. Application retained as it was.'});render();}else if(el.id==='confirm-import'&&importPreview){let p=importPreview;pendingChat=null;chat=[];state={apps:p.apps,territories:p.territories,reference:E.benchmarks(p.apps),settings:{minInvestment:'',minArea:'',minLaunch:''},tasks:{},taskDates:{},audit:[],source:p.source,warnings:p.warnings};audit(`Imported ${p.apps.length} applications and ${p.territories.length} territories from ${p.source}.`);save();importPreview=null;tab=pendingCount()?'review':'applications';location.hash=tab;filter='';query='';render();toast('Import complete. Every application is retained.');}else if(el.id==='help'){modal(`<div class="drawer-head"><h2>Your expansion workspace</h2><button class="close" data-close aria-label="Close dialog">×</button></div><ol class="help-list"><li>Upload the supplied XLSX format. Row 3 examples are excluded unless selected.</li><li>Confirm proposed cleaning and fill missing fields.</li><li>Review scores and territory recommendations.</li><li>Ask the assistant for a reason or confirm a field update.</li><li>Verify funding, inspect the site and track opening readiness.</li></ol><div class="info-row">Data stays in this browser. Export a JSON backup to preserve your work or use another device. Other visitors have separate workspaces. The assistant uses supported rules and patterns; it does not call an external AI model.</div>`);}});
document.addEventListener('submit',e=>{if(e.target.id!=='edit-form')return;e.preventDefault();let form=e.target,patch=Object.fromEntries(new FormData(form));for(let f of E.numeric)patch[f]=patch[f]===''?null:Number(patch[f]);for(let f of E.fields)if(!E.numeric.includes(f))patch[f]=patch[f].trim()||null;applyPatch(form.dataset.key,patch,'Confirmed application details');detail(form.dataset.key);toast('Application updated. All affected allocations reassessed.');});
document.addEventListener('change',e=>{let d=e.target.dataset;if(d.task){let key=d.task,i=Number(d.taskIndex);state.tasks[key]??={};state.tasks[key][i]=e.target.checked;if(!e.target.checked)for(let j=i+1;j<7;j++)state.tasks[key][j]=false;audit(`${state.apps.find(a=>a.key===key)?.id}: ${taskDefs[i][0]} ${e.target.checked?'completed':'reopened; later steps reset'}.`);save();render();detail(key);}else if(d.taskDate){state.taskDates[d.taskDate]??={};state.taskDates[d.taskDate][d.taskIndex]=e.target.value;save();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();let r=e.target.closest('tr[data-detail]');if(r&&e.key==='Enter')detail(r.dataset.detail);if(e.key==='Tab'&&!$('#overlay').hidden){let f=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href],summary')].filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus();}}});
$('#overlay').onclick=e=>{if(e.target===$('#overlay'))close();};$('#file').onchange=e=>parseFile(e.target.files[0]);$('#restore-file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('Backup is too large.');let p=JSON.parse(await f.text());if(p.version!==1||!E.validState(p.state))throw Error('This is not a valid FranchiseOS backup.');E.assess(p.state.apps,p.state.territories,stores,p.state.reference,p.state.settings);if(!confirm('Replace this browser’s workspace with the backup?'))return;pendingChat=null;chat=[];state=p.state;state.taskDates??={};state.tasks??={};state.audit??=[];state.warnings??=[];audit('Restored workspace from a JSON backup.');save();close();tab='overview';location.hash=tab;render();toast('Backup restored.');}catch(err){toast(err.message||'Backup could not be restored.');}e.target.value='';};
window.addEventListener('hashchange',()=>{tab=location.hash.slice(1)||'overview';render();});
(async()=>{try{const s=localStorage.getItem('franchise-os-v1');if(s){let p=JSON.parse(s);if(E.validState(p)){state=p;state.taskDates??={};tab=location.hash.slice(1)||'overview';render();return;}}}catch(e){storageOK=false;}await loadDemo(true);})();
